/**
 * One row of a deviation chart (G7a): [name] („Mo“), [value] its signed difference from the midpoint on the scale,
 * [valueText] the same as text with its sign and unit („+0,5 Std.“, „−1,0 Std.“ with U+2212 and U+00A0, spec/07).
 */
@Immutable
data class SbDeviation(val name: String, val value: Float, val valueText: String)

/**
 * Deviation (G7a, spec/02 §3.7 `sb-chart__diverging`): one column grid for all rows, name (caption, text) · bar ·
 * value (the 16 dp arrow up or down, none at 0, and [SbDeviation.valueText] in caption, tabular, text), 12 dp apart.
 * The bar is 32 dp high at every width (size.controlSm, the row's minimum), the fill 16 dp in its middle: less from
 * the 1 dp chartAxis zero line towards the start in dataviz.diverging[1], more towards the end in diverging[3]
 * (classes 2 and 4: tones, never good or bad); [max] = the difference a half bar shows (else the largest; when every
 * difference is 0 there are no fills, only the zero line). Over the
 * bar column the head: [less] at the start, [midpoint] („0 = 7 Std.“) on the zero line, [more] at the end, caption
 * textMuted, 4 dp above the rows; when the sides do not fit beside the midpoint, the three stand one under the other. A row grows with its text, the zero line runs through. Right to left the bars
 * mirror with the columns. TalkBack: the caption, the head as one node, then one node per row („Mo: +0,5 Std.“).
 */
@Composable
fun SbDeviationChart(
    rows: List<SbDeviation>,
    midpoint: String,
    caption: String,
    modifier: Modifier = Modifier,
    less: String = sbMessages().chartLess,
    more: String = sbMessages().chartMore,
    max: Float? = null,
) {
    require(rows.isNotEmpty()) { "SbDeviationChart: no rows" }
    // every difference 0 (one night, an even week): no fills, only the zero line, not an error
    val scale = max ?: rows.maxOf { if (it.value < 0f) -it.value else it.value }.takeIf { it > 0f } ?: 1f
    require(scale > 0f) { "SbDeviationChart: max must be above 0" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val dv = SebaroTheme.dataviz
    val m = sbMessages()
    val text = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    SbBoundedChartFigure(caption, modifier) {
        Layout(
            content = {
                // per part: the shown pieces are hidden, a node over them reads them as one
                listOf(less, midpoint, more).forEach { Text(it, style = text, color = c.textMuted, modifier = Modifier.clearAndSetSemantics { }) }
                Box(Modifier.semantics(mergeDescendants = true) { contentDescription = listOf(less, midpoint, more).joinToString(", ") })
                rows.forEach { r ->
                    Text(r.name, style = ty.caption, color = c.text, modifier = Modifier.clearAndSetSemantics { })
                    Canvas(Modifier.clearAndSetSemantics { }) {
                        val zero = size.width / 2f
                        val half = zero * ((if (r.value < 0f) -r.value else r.value) / scale).coerceIn(0f, 1f)
                        val toLeft = (r.value < 0f) != (layoutDirection == LayoutDirection.Rtl)
                        val fill = t.size.controlSm.toPx() / 2f
                        if (half > 0f) {
                            drawRect(
                                if (r.value < 0f) dv.diverging[1] else dv.diverging[3],
                                Offset(if (toLeft) zero - half else zero, (size.height - fill) / 2f),
                                Size(half, fill),
                            )
                        }
                        drawLine(t.x.chartAxis, Offset(zero, 0f), Offset(zero, size.height), t.borderWidth.hairline.toPx())
                    }
                    Row(
                        Modifier.clearAndSetSemantics { },
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(t.space.s1),
                    ) {
                        if (r.value != 0f) {
                            Icon(
                                if (r.value > 0f) SebaroIcons.Outline16.ArrowUp else SebaroIcons.Outline16.ArrowDown,
                                contentDescription = null,
                                tint = c.text,
                                modifier = Modifier.size(t.size.iconSm),
                            )
                        }
                        Text(r.valueText, style = text, color = c.text)
                    }
                    Box(Modifier.semantics(mergeDescendants = true) { contentDescription = m.chartPoint(r.name, r.valueText) })
                }
            },
            modifier = Modifier.fillMaxWidth(),
        ) { measurables, constraints ->
            val w = constraints.maxWidth
            val gap = t.space.s3.roundToPx()
            val column = Constraints(maxWidth = (w * 0.4f).toInt())
            val names = rows.indices.map { measurables[4 + 4 * it].measure(column) }
            val values = rows.indices.map { measurables[6 + 4 * it].measure(column) }
            val nameW = names.maxOf { it.width }
            val barW = (w - nameW - values.maxOf { it.width } - 2 * gap).coerceAtLeast(0)
            val x0 = nameW + gap
            val whole = Constraints(maxWidth = w)
            val lessText = measurables[0].measure(whole)
            val mid = measurables[1].measure(whole)
            val moreText = measurables[2].measure(whole)
            // one line when both sides fit beside the midpoint (8 dp apart); else one under the other, each still
            // towards its side and the midpoint on the zero line, never cut inside a word
            val side = (barW - mid.width) / 2 - t.space.s2.roundToPx()
            val oneLine = lessText.width <= side && moreText.width <= side
            val midY = if (oneLine) 0 else lessText.height
            val moreY = if (oneLine) 0 else midY + mid.height
            val headH = if (oneLine) maxOf(lessText.height, mid.height, moreText.height) else moreY + moreText.height
            val headNode = measurables[3].measure(Constraints.fixed(w, headH))
            val heights = rows.indices.map { maxOf(t.size.controlSm.roundToPx(), names[it].height, values[it].height) }
            val bars = rows.indices.map { measurables[5 + 4 * it].measure(Constraints.fixed(barW, heights[it])) }
            val nodes = rows.indices.map { measurables[7 + 4 * it].measure(Constraints.fixed(w, heights[it])) }
            val below = t.space.s1.roundToPx()
            layout(w, headH + below + heights.sum()) {
                lessText.placeRelative(x0.coerceAtMost(w - lessText.width), 0)
                mid.placeRelative((x0 + (barW - mid.width) / 2).coerceIn(0, (w - mid.width).coerceAtLeast(0)), midY)
                moreText.placeRelative((x0 + barW - moreText.width).coerceAtLeast(0), moreY)
                headNode.placeRelative(0, 0)
                var y = headH + below
                rows.indices.forEach { i ->
                    val h = heights[i]
                    names[i].placeRelative(0, y + (h - names[i].height) / 2)
                    bars[i].placeRelative(x0, y)
                    values[i].placeRelative(w - values[i].width, y + (h - values[i].height) / 2)
                    nodes[i].placeRelative(0, y)
                    y += h
                }
            }
        }
    }
}
